from pysat.solvers import Glucose3

# K_9 has 9 vertices, edges are (i,j) for 0 <= i < j <= 8
# Total edges: 36
# We'll map each edge (i,j) to a variable index 0..35

edge_to_var = {}
var_to_edge = {}
idx = 0
for i in range(9):
    for j in range(i+1, 9):
        edge_to_var[(i, j)] = idx
        var_to_edge[idx] = (i, j)
        idx += 1

solver = Glucose3()

# Constraint 1: No red K_4
# For every set of 4 vertices, at least one edge must be blue (1)
# If edge is red, var = 0. If blue, var = 1.
# So for each 4-clique, we need at least one var = 1.
# Clause: (v1 OR v2 OR v3 OR v4 OR v5 OR v6) where v's are the 6 edges
from itertools import combinations

for vertices in combinations(range(9), 4):
    edges = []
    for i in range(4):
        for j in range(i+1, 4):
            u, v = vertices[i], vertices[j]
            if u > v:
                u, v = v, u
            edges.append(edge_to_var[(u, v)] + 1)  # +1 for 1-based SAT vars
    solver.add_clause(edges)

# Constraint 2: No blue K_3
# For every set of 3 vertices, at least one edge must be red (0)
# If edge is blue, var = 1. If red, var = 0.
# So for each 3-clique, we need at least one var = 0.
# Clause: (-v1 OR -v2 OR -v3)
for vertices in combinations(range(9), 3):
    edges = []
    for i in range(3):
        for j in range(i+1, 3):
            u, v = vertices[i], vertices[j]
            if u > v:
                u, v = v, u
            edges.append(-(edge_to_var[(u, v)] + 1))
    solver.add_clause(edges)

if solver.solve():
    model = solver.get_model()
    print("SATISFIABLE")
    solution = []
    for i in range(36):
        val = model[i]
        if val > 0:
            solution.append(1)  # blue
        else:
            solution.append(0)  # red
    print(solution)
else:
    print("UNSATISFIABLE")

# Let's verify the Ramsey number R(4,3)
# R(4,3) is the smallest n such that any 2-coloring of K_n has a red K_4 or blue K_3
# Known result: R(4,3) = 9

# This means K_9 cannot be 2-colored without a red K_4 or blue K_3
# So the answer is UNSATISFIABLE

# Let's double-check by trying K_8 to see if it's satisfiable
from pysat.solvers import Glucose3
from itertools import combinations

edge_to_var = {}
idx = 0
for i in range(8):
    for j in range(i+1, 8):
        edge_to_var[(i, j)] = idx
        idx += 1

solver = Glucose3()

# No red K_4
for vertices in combinations(range(8), 4):
    edges = []
    for i in range(4):
        for j in range(i+1, 4):
            u, v = vertices[i], vertices[j]
            if u > v:
                u, v = v, u
            edges.append(edge_to_var[(u, v)] + 1)
    solver.add_clause(edges)

# No blue K_3
for vertices in combinations(range(8), 3):
    edges = []
    for i in range(3):
        for j in range(i+1, 3):
            u, v = vertices[i], vertices[j]
            if u > v:
                u, v = v, u
            edges.append(-(edge_to_var[(u, v)] + 1))
    solver.add_clause(edges)

if solver.solve():
    print("K_8 is SATISFIABLE (as expected, since R(4,3)=9)")
else:
    print("K_8 is UNSATISFIABLE")
